import { Style, When } from '@pleat/core'
import { complexTokens } from '../complex-tokens'
import { interactionTokens } from '../interaction-tokens'
import { tokens } from '../tokens'

export const styles = {
  root: Style.make({
    gap: '1rem',
    display: 'flex',
    flexDirection: 'column',
    minWidth: 0,
    width: '100%',
  }),
  toolbar: Style.make({
    gap: '0.75rem',
    alignItems: 'center',
    display: 'flex',
    flexWrap: 'wrap',
    justifyContent: 'space-between',
  }),
  filter: Style.make({
    borderColor: tokens.input,
    borderRadius: tokens.controlRadius,
    borderStyle: 'solid',
    borderWidth: 1,
    paddingInline: '0.75rem',
    backgroundColor: tokens.transparent,
    boxShadow: tokens.shadowSm,
    fontSize: '0.875rem',
    outlineStyle: 'none',
    height: '2.5rem',
    maxWidth: '24rem',
    width: '100%',
  }).pipe(
    Style.when(When.focusVisible, {
      borderColor: tokens.ring,
      boxShadow: tokens.focusRingShadow,
    }),
  ),
  summary: Style.make({
    color: tokens.mutedForeground,
    fontSize: '0.8125rem',
    fontVariantNumeric: 'tabular-nums',
    whiteSpace: 'nowrap',
  }),
  shell: Style.make({
    borderColor: tokens.border,
    borderRadius: tokens.cardRadius,
    borderStyle: 'solid',
    borderWidth: 1,
    overflow: 'hidden',
    boxShadow: tokens.shadowSm,
    minWidth: 0,
  }),
  horizontalScroll: Style.make({ minWidth: 0, overflowX: 'auto' }),
  table: Style.make({ minWidth: '58rem', width: '100%' }),
  header: Style.make({
    alignItems: 'center',
    backgroundColor: complexTokens.mutedSurface,
    display: 'grid',
    borderBottomColor: tokens.border,
    borderBottomStyle: 'solid',
    borderBottomWidth: 1,
    minHeight: '2.75rem',
  }),
  heading: Style.make({
    paddingInline: '0.75rem',
    alignItems: 'center',
    color: tokens.mutedForeground,
    display: 'flex',
    fontSize: '0.6875rem',
    fontWeight: 600,
    letterSpacing: '0.055em',
    textTransform: 'uppercase',
    minWidth: 0,
  }),
  sortButton: Style.make({
    borderRadius: tokens.controlRadius,
    gap: '0.375rem',
    alignItems: 'center',
    color: tokens.mutedForeground,
    cursor: interactionTokens.cursorAction,
    display: 'inline-flex',
    outlineColor: tokens.transparent,
    outlineStyle: 'none',
    outlineWidth: 0,
    transform: 'scale(1)',
    transitionDuration: interactionTokens.motionFast,
    transitionProperty: 'color, transform',
    minHeight: '2.5rem',
  }).pipe(
    Style.when(When.hover, { color: tokens.foreground }),
    Style.when(When.focusVisible, {
      outlineColor: tokens.ring,
      outlineStyle: 'solid',
      outlineWidth: 2,
    }),
    Style.when(When.active, {
      transform: interactionTokens.pressTransformTactile,
    }),
  ),
  sortIcon: Style.make({ height: '0.875rem', width: '0.875rem' }),
  viewport: Style.make({ overscrollBehavior: 'contain', height: '26rem' }),
  row: Style.make({
    alignItems: 'center',
    backgroundColor: tokens.transparent,
    display: 'grid',
    transitionDuration: interactionTokens.motionFast,
    transitionProperty: 'background-color',
    borderBottomColor: tokens.border,
    borderBottomStyle: 'solid',
    borderBottomWidth: 1,
    height: '100%',
  }).pipe(
    Style.when(When.hover, { backgroundColor: complexTokens.mutedSurface }),
  ),
  rowSelected: Style.make({ backgroundColor: complexTokens.mutedSurface }),
  cell: Style.make({
    overflow: 'hidden',
    paddingInline: '0.75rem',
    fontSize: '0.8125rem',
    textOverflow: 'ellipsis',
    whiteSpace: 'nowrap',
    minWidth: 0,
  }),
  numeric: Style.make({ fontVariantNumeric: 'tabular-nums' }),
  selectionCell: Style.make({
    padding: 0,
    alignItems: 'center',
    display: 'flex',
    justifyContent: 'center',
  }),
  selectionButton: Style.make({
    padding: 0,
    borderWidth: 0,
    alignItems: 'center',
    backgroundColor: tokens.transparent,
    display: 'inline-flex',
    justifyContent: 'center',
    height: '2.5rem',
    width: '2.5rem',
  }),
  selectionBox: Style.make({
    borderColor: tokens.input,
    borderRadius: complexTokens.smallRadius,
    borderStyle: 'solid',
    borderWidth: 1,
    alignItems: 'center',
    backgroundColor: tokens.background,
    color: tokens.primaryForeground,
    display: 'flex',
    justifyContent: 'center',
    height: '1rem',
    width: '1rem',
  }),
  selectionBoxChecked: Style.make({
    borderColor: tokens.primary,
    backgroundColor: tokens.primary,
  }),
  selectionIcon: Style.make({ height: '0.75rem', width: '0.75rem' }),
  empty: Style.make({
    alignItems: 'center',
    color: tokens.mutedForeground,
    display: 'flex',
    fontSize: '0.875rem',
    justifyContent: 'center',
    height: '8rem',
  }),
}
